import{_ as a,c as n,o as t,ag as i}from"./chunks/framework.CoPVQkzc.js";const p=JSON.parse('{"title":"Installing Open Integration Engine","description":"System requirements, choosing an installer, and installing on Windows, macOS and Linux","frontmatter":{"title":"Installing Open Integration Engine","description":"System requirements, choosing an installer, and installing on Windows, macOS and Linux"},"headers":[],"relativePath":"engine/installation.md","filePath":"engine/installation.md","lastUpdated":1788382105000}'),o={name:"engine/installation.md"};function s(r,e,l,d,c,h){return t(),n("div",null,e[0]||(e[0]=[i('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Open Integration Engine™️, also called OIE™️ in this documentation, installs from a native installer on Windows, macOS and Linux.</p><h2 id="system-requirements" tabindex="-1">System requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System requirements&quot;">​</a></h2><p>The OIE Server operates as a completely self-contained application and does not depend on any external application server.</p><h3 id="java-requirements" tabindex="-1">Java requirements <a class="header-anchor" href="#java-requirements" aria-label="Permalink to &quot;Java requirements&quot;">​</a></h3><p>The Open Integration Engine requires Java 17+ to work.</p><h3 id="database-requirements" tabindex="-1">Database requirements <a class="header-anchor" href="#database-requirements" aria-label="Permalink to &quot;Database requirements&quot;">​</a></h3><p>OIE uses an embedded Apache Derby database by default, which allows you to store configuration and messages, for the purpose of rapid deployment, development and testing.</p><p>For production deployments, it is recommended to use only database versions currently receiving official security and maintenance support from their respective vendors. The following database engines are supported as backends:</p><ul><li>PostgreSQL</li><li>MySQL / MariaDB</li><li>Oracle</li><li>SQL Server</li></ul><h2 id="download-and-installation" tabindex="-1">Download and installation <a class="header-anchor" href="#download-and-installation" aria-label="Permalink to &quot;Download and installation&quot;">​</a></h2><p>Every release publishes native installers for Windows, macOS and Linux on the <a href="https://github.com/OpenIntegrationEngine/engine/releases/latest" target="_blank" rel="noreferrer">releases page</a>, plus <code>.tar.gz</code> and <code>.zip</code> archives for Linux and Windows. The installer is the quickest way to get started: it installs the application, registers OIE as a native service, and sets it to start on boot. If you would rather do it by hand, see <a href="#installing-from-an-archive">Installing from an archive</a>.</p><h3 id="choosing-an-installer" tabindex="-1">Choosing an installer <a class="header-anchor" href="#choosing-an-installer" aria-label="Permalink to &quot;Choosing an installer&quot;">​</a></h3><p>Each platform ships in two flavors.</p><p><strong>With JRE</strong> bundles Azul Zulu 17, so nothing else needs installing and the runtime the server uses is known and fixed. Take this one unless you have a reason not to.</p><p><strong>Without JRE</strong> is smaller and runs on whatever Java 17 or newer is already on the machine. Choose it when Java is managed centrally or already hardened to a standard you have to meet.</p><p>The bundled flavor is between about 55MB and 280MB larger depending on platform, which is the only difference between the two.</p><p>Pick the build that matches your architecture: <code>aarch</code> for Apple silicon and <code>x86</code> for Intel Macs, <code>x64</code> or <code>arm64</code> on Windows. Each release also publishes <code>sha256sums</code> and <code>md5sums</code>.</p><h3 id="installing" tabindex="-1">Installing <a class="header-anchor" href="#installing" aria-label="Permalink to &quot;Installing&quot;">​</a></h3><p>Open the file you downloaded:</p><ul><li><strong>Windows</strong>: run the <code>.exe</code>.</li><li><strong>macOS</strong>: mount the <code>.dmg</code> and launch the installer inside it.</li><li><strong>Linux</strong>: make the <code>.sh</code> executable with <code>chmod +x</code>, then run it.</li></ul><p>Then follow the wizard: accept the Mozilla Public License 2.0, choose an installation directory, and click <code>Finish</code>. The installer requires administrative rights, because registering a system service does.</p><p>On a headless machine the installer detects that no display is available and runs as a console installer instead. No flag is required, so the same file works on a server and on a desktop.</p><div class="warning custom-block"><p class="custom-block-title">Your operating system will warn about the installer</p><p>Windows and macOS check downloaded programs for a code signature. That is a stamp the publisher puts on a file, so the operating system can confirm where it came from and that nobody has changed it. The OIE installer does not have one, so you will see a security warning.</p><p>On Windows the warning comes from SmartScreen, and often from the browser as well. On macOS, Gatekeeper blocks the <code>.dmg</code> the first time you open it. Allow it under System Settings, Privacy &amp; Security. The wording varies by version.</p><p>The jars inside are signed. The Administrator client and the bundled extensions carry a signature from a certificate authority with a trusted timestamp. Only the installer that wraps them is missing one.</p><p>Check your download against the published <code>sha256sums</code> and continue.</p></div><div class="warning custom-block"><p class="custom-block-title">Install directory and sudo</p><p>Installing into a directory you do not own, such as the default <code>/Applications/OpenIntegrationEngine</code> on macOS, means anything you later run by hand needs <code>sudo</code>.</p></div><h3 id="installing-from-an-archive" tabindex="-1">Installing from an archive <a class="header-anchor" href="#installing-from-an-archive" aria-label="Permalink to &quot;Installing from an archive&quot;">​</a></h3><p>The release also publishes <code>oie_unix_&lt;version&gt;.tar.gz</code> and <code>oie_windows-&lt;arch&gt;_&lt;version&gt;.zip</code> for a manual install. Unpack the archive wherever you want it and run <code>oieserver</code> from the extracted directory.</p><p>Nothing is registered with the service manager and nothing starts on boot, so you have to wire it into systemd, launchd or the Windows service manager yourself. Take this route when you want that control, or when you cannot give an installer administrative rights.</p><p>Once it is installed, see <a href="./server_process_management.html">Server Process Management</a>.</p>',29)]))}const m=a(o,[["render",s]]);export{p as __pageData,m as default};
